std::vector<std::pair<double, TreeNode<int>*>> nodes;
for (int i = 0; i < size; i++) {
    TreeNode<int>* leaf = new TreeNode<int>(values[i]);
    nodes.emplace_back(freqs[i], leaf);
}

std::sort(nodes.begin(), nodes.end(), [](const auto& a, const auto& b) {
    return a.first < b.first;
});

while (nodes.size() > 1) {
    auto left = nodes.front(); nodes.erase(nodes.begin());
    auto right = nodes.front(); nodes.erase(nodes.begin());

    TreeNode<int>* parent = new TreeNode<int>(-1);
    parent->left = left.second;
    parent->right = right.second;

    nodes.emplace_back(left.first + right.first, parent);
    std::sort(nodes.begin(), nodes.end(), [](const auto& a, const auto& b) {
        return a.first < b.first;
    });
}

return nodes.empty() ? nullptr : nodes[0].second;

